      inputs: [bi('אותות התיק (הכללים המתועדים)', 'the dossier signals (the documented rules)'), bi('איכות הראיות של התיק', 'the dossier evidence quality'), bi('רשומות שמורות: מכרזים בהיקף הנוכחי + מכרזי השכרה; מתחמי התחדשות + פרויקטי הגרלה כפי שפורסמו (מכל תאריך)', 'stored records: current-scope tenders + rental tenders; renewal complexes + lottery projects as published (any date)')],
