      formula: bi('עכשיו = F0–F5(כלכלה קפואה, הערכה חדשה); הפרש = עכשיו − אז', 'now = F0–F5(frozen economics, new assessment); delta = now − then'), inputs: [bi('תמונת ההחלטה; הקריאה הנוכחית', 'the decision snapshot; the current read')],
