    'SITE_CLOSURE_NOTICE': { term: 'active_construction_site', kind: 'watch', rule: bi("≥ 1 הודעת סגירת אתר של מינהל הבטיחות בשם הקבלן המנורמל", "≥ 1 safety-administration site-closure notice under the normalized contractor name") },
    'EXECUTION_GAP': { term: 'execution_gap', kind: 'watch', rule: bi("≥ 18 חודשים מאז הראיה הציבורית המתוארכת האחרונה, הסולם מתחת לגמר, ומקור בכיסוי היה יכול להראות ראיה מאוחרת יותר — פער ראיות, לא עצירה", "≥ 18 months since the last dated public evidence, the ladder below completion, and a source in coverage could have shown later evidence — an evidence gap, not a stop") },
